SELECT CASE WHEN budget >= 3847000 THEN 'high' WHEN budget >= 1150000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(STDDEV(budget), 2) AS stddev_budget, COUNT(DISTINCT budget) AS unique_locations, SUM(CASE WHEN dept_name = 'Engineering' THEN budget ELSE 0 END) AS engineering_budget FROM departments WHERE budget >= 2193000 AND location NOT IN ('Chiang Mai', 'Bangkok', 'New York') GROUP BY CASE WHEN budget >= 3847000 THEN 'high' WHEN budget >= 1150000 THEN 'mid' ELSE 'low' END HAVING ROUND(STDDEV(budget), 2) >= 41
